window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["runwayml"]={html:"<div class=\"own-runwayml\">\n  <header class=\"rw-nav\" id=\"rwTop\">\n    <a class=\"rw-brand\" href=\"#rw-top\" aria-label=\"Northwind home\">\n      <span>Northwind</span>\n    </a>\n    <nav class=\"rw-menu\" aria-label=\"Primary\">\n      <a href=\"#rw-research\">Research</a>\n      <a href=\"#rw-grid\">Work</a>\n      <a href=\"#rw-trust\">Customers</a>\n      <a href=\"#rw-mission\">Mission</a>\n    </nav>\n    <div class=\"rw-nav-right\">\n      <a class=\"rw-link\" href=\"#\">Log in</a>\n      <a class=\"rw-btn\" href=\"#rw-mission\">Get started</a>\n      <button class=\"rw-burger\" type=\"button\" aria-label=\"Menu\" data-rw-burger><span></span><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"rw-top\">\n    <section class=\"rw-hero\" aria-labelledby=\"rw-h1\">\n      <div class=\"rw-hero-scene\" aria-hidden=\"true\">\n        <span class=\"rw-frame rw-frame-1\"></span>\n        <span class=\"rw-frame rw-frame-2\"></span>\n        <span class=\"rw-frame rw-frame-3\"></span>\n        <span class=\"rw-grain\"></span>\n      </div>\n      <div class=\"rw-hero-inner\">\n        <p class=\"rw-label\">Operations analytics</p>\n        <h1 id=\"rw-h1\" class=\"rw-h1\">Simulate the<br>whole floor</h1>\n        <p class=\"rw-hero-sub\">Read every region, line, and shift as one continuous picture &#8212; then ask the question that changes tomorrow.</p>\n        <div class=\"rw-hero-cta\">\n          <a class=\"rw-btn rw-btn-light\" href=\"#rw-grid\">Explore the work</a>\n          <a class=\"rw-btn rw-btn-ghost\" href=\"#rw-mission\">Our mission</a>\n        </div>\n      </div>\n    </section>\n\n    <section id=\"rw-grid\" class=\"rw-section\" aria-labelledby=\"rw-grid-h\">\n      <div class=\"rw-sec-head\">\n        <p class=\"rw-label\">Selected scenes</p>\n        <h2 id=\"rw-grid-h\" class=\"rw-h2\">An editorial grid of operations</h2>\n      </div>\n      <div class=\"rw-grid\">\n        <article class=\"rw-tile rw-tile-lg\">\n          <div class=\"rw-tile-img rw-img-a\" aria-hidden=\"true\"></div>\n          <div class=\"rw-tile-copy\">\n            <p class=\"rw-tile-meta\">Feature &#183; 8 min read</p>\n            <h3 class=\"rw-tile-title\">The line that learned to predict itself</h3>\n          </div>\n        </article>\n        <article class=\"rw-tile\">\n          <div class=\"rw-tile-img rw-img-b\" aria-hidden=\"true\"></div>\n          <div class=\"rw-tile-copy\">\n            <p class=\"rw-tile-meta\">Research &#183; 5 min</p>\n            <h3 class=\"rw-tile-title\">Cost attribution at the speed of the shift</h3>\n          </div>\n        </article>\n        <article class=\"rw-tile\">\n          <div class=\"rw-tile-img rw-img-c\" aria-hidden=\"true\"></div>\n          <div class=\"rw-tile-copy\">\n            <p class=\"rw-tile-meta\">Field note &#183; 4 min</p>\n            <h3 class=\"rw-tile-title\">Ports, hubs, and one source of truth</h3>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section id=\"rw-research\" class=\"rw-section rw-section-light\" aria-labelledby=\"rw-research-h\">\n      <div class=\"rw-sec-head\">\n        <p class=\"rw-label rw-label-light\">Research articles</p>\n        <h2 id=\"rw-research-h\" class=\"rw-h2 rw-h2-light\">From signal to decision</h2>\n      </div>\n      <div class=\"rw-articles\">\n        <article class=\"rw-article\">\n          <p class=\"rw-article-meta\">Method &#183; 2026</p>\n          <h3 class=\"rw-article-title\">A metric defined once, reconciled everywhere</h3>\n          <p class=\"rw-article-copy\">How a single definition removes the weekly argument over whose number is right.</p>\n          <a class=\"rw-article-link\" href=\"#\">Read the article<span aria-hidden=\"true\">&#8594;</span></a>\n        </article>\n        <article class=\"rw-article\">\n          <p class=\"rw-article-meta\">Systems &#183; 2026</p>\n          <h3 class=\"rw-article-title\">Streaming a floor without a batch window</h3>\n          <p class=\"rw-article-copy\">Every source reports as it runs. Northwind reconciles in the moment, not overnight.</p>\n          <a class=\"rw-article-link\" href=\"#\">Read the article<span aria-hidden=\"true\">&#8594;</span></a>\n        </article>\n        <article class=\"rw-article\">\n          <p class=\"rw-article-meta\">Craft &#183; 2026</p>\n          <h3 class=\"rw-article-title\">Designing an interface that stays invisible</h3>\n          <p class=\"rw-article-copy\">Depth comes from the data, not the chrome. A note on restraint as a design decision.</p>\n          <a class=\"rw-article-link\" href=\"#\">Read the article<span aria-hidden=\"true\">&#8594;</span></a>\n        </article>\n      </div>\n    </section>\n\n    <section id=\"rw-trust\" class=\"rw-section\" aria-labelledby=\"rw-trust-h\">\n      <p class=\"rw-label rw-label-center\">Trusted by operations teams</p>\n      <h2 id=\"rw-trust-h\" class=\"rw-h2 rw-h2-center\">Leading organizations, one operating picture</h2>\n      <div class=\"rw-trust-bar\" aria-label=\"Customer logos\">\n        <span>LUZON&nbsp;MFG</span>\n        <span>BUSAN&nbsp;PORT</span>\n        <span>SYDNEY&nbsp;HUB</span>\n        <span>MINDANAO&nbsp;AGRI</span>\n        <span>ROTTERDAM&nbsp;REC</span>\n        <span>DUBAI&nbsp;TRADE</span>\n      </div>\n    </section>\n\n    <section class=\"rw-stats\" aria-labelledby=\"rw-stats-h\">\n      <h2 id=\"rw-stats-h\" class=\"rw-sr\">Northwind by the numbers</h2>\n      <div class=\"rw-stats-grid\">\n        <div class=\"rw-stat\"><b>78%</b><span>Average OEE across sample plants</span></div>\n        <div class=\"rw-stat\"><b>98.1%</b><span>On-time delivery, sample network</span></div>\n        <div class=\"rw-stat\"><b>$12.4M</b><span>Throughput tracked per quarter</span></div>\n        <div class=\"rw-stat\"><b>&lt;1s</b><span>From source report to board</span></div>\n      </div>\n    </section>\n\n    <section id=\"rw-mission\" class=\"rw-mission\" aria-labelledby=\"rw-mission-h\">\n      <p class=\"rw-label rw-label-center\">Our mission</p>\n      <h2 id=\"rw-mission-h\" class=\"rw-mission-h\">We are building operations intelligence to give every team one honest number.</h2>\n      <div class=\"rw-mission-cta\">\n        <a class=\"rw-btn rw-btn-light rw-btn-lg\" href=\"#\">Start free</a>\n        <a class=\"rw-btn rw-btn-ghost rw-btn-lg\" href=\"#\">Talk to us</a>\n      </div>\n    </section>\n  </main>\n\n  <footer class=\"rw-foot\">\n    <div class=\"rw-foot-inner\">\n      <div class=\"rw-foot-brand\">\n        <span>Northwind</span>\n        <p>Sample data &#8212; showcase only. People and numbers are fictional.</p>\n      </div>\n      <div class=\"rw-foot-cols\">\n        <h3>Product</h3><a href=\"#\">Boards</a><a href=\"#\">Alerts</a><a href=\"#\">Forecast</a><a href=\"#\">Changelog</a>\n      </div>\n      <div class=\"rw-foot-cols\">\n        <h3>Research</h3><a href=\"#\">Articles</a><a href=\"#\">Method</a><a href=\"#\">Systems</a><a href=\"#\">Craft</a>\n      </div>\n      <div class=\"rw-foot-cols\">\n        <h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Press</a><a href=\"#\">Legal</a>\n      </div>\n    </div>\n    <div class=\"rw-foot-bottom\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <span>Terms &#183; Privacy &#183; Cookies</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the Runway design language, for showcase.html ══════════\n   Cinematic dark editorial canvas, one typeface (abcNormal-style geometric\n   sans), cool-slate neutrals, tight display type at line-height 1.0 with\n   negative tracking, uppercase labels with positive tracking, zero shadows,\n   images as the primary visual element (built here from CSS gradients + SVG). */\n\n.own-runwayml {\n  --black: #000000;\n  --deep: #030303;\n  --surface: #1a1a1a;\n  --white: #ffffff;\n  --near-white: #fefefe;\n  --cloud: #e9ecf2;\n  --border-dark: #27272a;\n  --charcoal: #404040;\n  --near-charcoal: #3f3f3f;\n  --slate: #767d88;\n  --slate-mid: #7d848e;\n  --muted-gray: #a7a7a7;\n  --silver: #c9ccd1;\n  --silver-light: #d0d4d4;\n  --footer-gray: #999999;\n\n  --r-sharp: 4px;\n  --r-subtle: 6px;\n  --r-comfort: 8px;\n  --r-generous: 16px;\n\n  --font: 'abcNormal', 'Inter', 'DM Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;\n  --gut: clamp(20px, 5cqi, 72px);\n  --section: 64px;\n\n  position: relative;\n  background: var(--black);\n  color: var(--slate);\n  font-family: var(--font);\n  font-size: 16px;\n  line-height: 1.4;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-runwayml *, .own-runwayml *::before, .own-runwayml *::after { box-sizing: border-box; }\n.own-runwayml a { color: inherit; text-decoration: none; }\n.own-runwayml button { font: inherit; cursor: pointer; }\n.own-runwayml :focus-visible { outline: 2px solid var(--white); outline-offset: 2px; border-radius: var(--r-sharp); }\n.own-runwayml .rw-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.own-runwayml .rw-label { font-size: 14px; font-weight: 500; line-height: 1.25; letter-spacing: .35px; text-transform: uppercase; color: var(--slate); }\n.own-runwayml .rw-label-light { color: var(--slate-mid); }\n.own-runwayml .rw-label-center { text-align: center; }\n.own-runwayml .rw-h2 { margin-top: 16px; font-size: clamp(28px, 4cqi, 40px); font-weight: 400; line-height: 1; letter-spacing: -1px; color: var(--white); }\n.own-runwayml .rw-h2-light { color: var(--charcoal); }\n\n/* ── nav (transparent over hero) ───────────────────────────────────────────── */\n.own-runwayml .rw-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 22px;\n  height: 72px; padding: 0 var(--gut);\n  background: rgba(0, 0, 0, .72); backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--border-dark);\n}\n.own-runwayml .rw-brand { color: var(--white); font-size: 18px; font-weight: 600; letter-spacing: -.02em; }\n.own-runwayml .rw-menu { display: flex; align-items: center; gap: 24px; margin: 0 auto; }\n.own-runwayml .rw-menu a { font-size: 16px; font-weight: 400; color: var(--silver); }\n.own-runwayml .rw-menu a:hover { color: var(--white); }\n.own-runwayml .rw-nav-right { display: flex; align-items: center; gap: 16px; margin-left: auto; }\n.own-runwayml .rw-link { font-size: 16px; color: var(--silver); }\n.own-runwayml .rw-link:hover { color: var(--white); }\n.own-runwayml .rw-burger { display: none; flex-direction: column; gap: 5px; width: 36px; height: 36px; align-items: center; justify-content: center; border: 1px solid var(--border-dark); border-radius: var(--r-sharp); background: transparent; }\n.own-runwayml .rw-burger span { display: block; width: 15px; height: 1.6px; background: var(--white); border-radius: 2px; }\n\n/* ── buttons (restrained, small radius) ────────────────────────────────────── */\n.own-runwayml .rw-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 40px; padding: 0 20px; border: 1px solid var(--border-dark); border-radius: var(--r-sharp); background: transparent; color: var(--white); font-size: 14px; font-weight: 600; letter-spacing: -.16px; transition: background-color .2s, border-color .2s; }\n.own-runwayml .rw-btn:hover { background: var(--surface); border-color: var(--silver); }\n.own-runwayml .rw-btn-light { background: var(--white); color: var(--black); border-color: var(--white); }\n.own-runwayml .rw-btn-light:hover { background: var(--silver); }\n.own-runwayml .rw-btn-ghost { background: transparent; color: var(--white); }\n.own-runwayml .rw-btn-lg { height: 48px; padding: 0 26px; font-size: 15px; }\n\n/* ── cinematic hero ─────────────────────────────────────────────────────────── */\n.own-runwayml .rw-hero { position: relative; overflow: hidden; min-height: 640px; display: flex; align-items: flex-end; }\n.own-runwayml .rw-hero-scene { position: absolute; inset: 0; background: radial-gradient(80% 90% at 70% 20%, #2b3346, #000 70%), linear-gradient(0deg, var(--black) 2%, transparent 60%); }\n.own-runwayml .rw-frame { position: absolute; border-radius: var(--r-comfort); }\n.own-runwayml .rw-frame-1 { left: 8%; top: 16%; width: 42%; height: 54%; background: linear-gradient(140deg, #40506e, #171b24 80%); }\n.own-runwayml .rw-frame-2 { left: 53%; top: 9%; width: 30%; height: 40%; background: linear-gradient(160deg, #6e5a40, #1c1712 80%); }\n.own-runwayml .rw-frame-3 { left: 56%; bottom: 10%; width: 36%; height: 34%; background: linear-gradient(120deg, #2e5a52, #0e1716 82%); }\n.own-runwayml .rw-grain { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0, 0, 0, .8) 4%, rgba(0, 0, 0, .1) 55%, transparent); }\n.own-runwayml .rw-hero-inner { position: relative; width: 100%; max-width: 1600px; margin: 0 auto; padding: 140px var(--gut) var(--section); }\n.own-runwayml .rw-h1 { margin-top: 16px; font-size: clamp(38px, 5.4cqi, 48px); font-weight: 400; line-height: 1; letter-spacing: -1.2px; color: var(--white); }\n.own-runwayml .rw-hero-sub { margin-top: 20px; max-width: 52ch; font-size: 16px; line-height: 1.5; letter-spacing: -.16px; color: var(--slate); }\n.own-runwayml .rw-hero-cta { display: flex; gap: 12px; margin-top: 28px; flex-wrap: wrap; }\n\n/* ── section shell ─────────────────────────────────────────────────────────── */\n.own-runwayml .rw-section { max-width: 1600px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-runwayml .rw-sec-head { margin-bottom: 32px; }\n\n/* ── editorial mixed-size grid ──────────────────────────────────────────────── */\n.own-runwayml .rw-grid { display: grid; grid-template-columns: 1.6fr 1fr; grid-template-rows: auto auto; gap: 20px; }\n.own-runwayml .rw-tile { display: grid; gap: 0; overflow: hidden; border-radius: var(--r-comfort); background: var(--surface); }\n.own-runwayml .rw-tile-lg { grid-row: span 2; }\n.own-runwayml .rw-tile-img { position: relative; min-height: 200px; overflow: hidden; }\n.own-runwayml .rw-tile-lg .rw-tile-img { min-height: 420px; }\n.own-runwayml .rw-img-a { background: radial-gradient(70% 80% at 30% 20%, #3a4a6b, #10141c 75%), linear-gradient(0deg, #0b0b0d, transparent 50%); }\n.own-runwayml .rw-img-b { background: radial-gradient(70% 80% at 70% 25%, #6b4a2e, #17110c 75%); }\n.own-runwayml .rw-img-c { background: radial-gradient(70% 80% at 40% 30%, #2b5a50, #0d1514 75%); }\n.own-runwayml .rw-tile-copy { padding: 20px 22px 24px; display: grid; gap: 6px; }\n.own-runwayml .rw-tile-meta { font-size: 11px; font-weight: 450; line-height: 1.3; text-transform: uppercase; letter-spacing: .35px; color: var(--muted-gray); }\n.own-runwayml .rw-tile-title { font-size: 24px; font-weight: 400; line-height: 1; letter-spacing: -.4px; color: var(--white); }\n.own-runwayml .rw-tile-lg .rw-tile-title { font-size: 32px; letter-spacing: -.8px; }\n.own-runwayml .rw-tile:hover .rw-tile-title { color: var(--silver); }\n\n/* ── light research band ─────────────────────────────────────────────────────── */\n.own-runwayml .rw-section-light { background: var(--cloud); color: var(--charcoal); max-width: none; padding: var(--section) var(--gut); margin-top: var(--section); }\n.own-runwayml .rw-articles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1600px; margin: 32px auto 0; }\n.own-runwayml .rw-article { display: grid; gap: 10px; padding-top: 20px; border-top: 1px solid var(--silver); align-content: start; }\n.own-runwayml .rw-article-meta { font-size: 11px; font-weight: 450; text-transform: uppercase; letter-spacing: .35px; color: var(--slate-mid); }\n.own-runwayml .rw-article-title { font-size: 24px; font-weight: 400; line-height: 1; letter-spacing: normal; color: var(--charcoal); }\n.own-runwayml .rw-article-copy { font-size: 14px; line-height: 1.3; letter-spacing: -.16px; color: var(--near-charcoal); }\n.own-runwayml .rw-article-link { display: inline-flex; align-items: center; gap: 8px; margin-top: 6px; font-size: 14px; font-weight: 600; letter-spacing: -.16px; color: var(--charcoal); border-bottom: 1px solid var(--charcoal); justify-self: start; padding-bottom: 2px; }\n.own-runwayml .rw-article-link:hover { gap: 12px; }\n\n/* ── trust bar ──────────────────────────────────────────────────────────────── */\n.own-runwayml .rw-trust-bar { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 20px 56px; margin-top: 36px; }\n.own-runwayml .rw-trust-bar span { font-size: 14px; font-weight: 450; letter-spacing: .35px; text-transform: uppercase; color: var(--footer-gray); }\n.own-runwayml .rw-h2-center { text-align: center; }\n\n/* ── stats band ─────────────────────────────────────────────────────────────── */\n.own-runwayml .rw-stats { max-width: 1600px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-runwayml .rw-stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-runwayml .rw-stat { display: grid; gap: 8px; padding-top: 20px; border-top: 1px solid var(--border-dark); }\n.own-runwayml .rw-stat b { font-size: 40px; font-weight: 400; line-height: 1; letter-spacing: -1px; color: var(--white); }\n.own-runwayml .rw-stat span { font-size: 14px; line-height: 1.3; letter-spacing: -.16px; color: var(--slate); }\n\n/* ── mission ────────────────────────────────────────────────────────────────── */\n.own-runwayml .rw-mission { background: var(--black); padding: 96px var(--gut); text-align: center; }\n.own-runwayml .rw-mission-h { max-width: 24ch; margin: 18px auto 0; font-size: clamp(28px, 3.4cqi, 36px); font-weight: 400; line-height: 1; letter-spacing: -.9px; color: var(--white); }\n.own-runwayml .rw-mission-cta { display: flex; justify-content: center; gap: 12px; margin-top: 32px; flex-wrap: wrap; }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-runwayml .rw-foot { border-top: 1px solid var(--border-dark); background: var(--deep); padding: 64px var(--gut) 28px; }\n.own-runwayml .rw-foot-inner { display: grid; grid-template-columns: 1.6fr 1fr 1fr 1fr; gap: 32px; max-width: 1600px; margin: 0 auto; }\n.own-runwayml .rw-foot-brand > span { font-size: 18px; font-weight: 600; color: var(--white); }\n.own-runwayml .rw-foot-brand p { margin-top: 10px; max-width: 34ch; font-size: 13px; line-height: 1.3; color: var(--footer-gray); }\n.own-runwayml .rw-foot-cols { display: grid; gap: 10px; align-content: start; }\n.own-runwayml .rw-foot-cols h3 { font-size: 11px; font-weight: 450; letter-spacing: .35px; text-transform: uppercase; color: var(--slate); margin-bottom: 4px; }\n.own-runwayml .rw-foot-cols a { font-size: 14px; color: var(--footer-gray); }\n.own-runwayml .rw-foot-cols a:hover { color: var(--white); }\n.own-runwayml .rw-foot-bottom { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1600px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--border-dark); font-size: 13px; color: var(--footer-gray); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-runwayml .rw-menu { display: none; }\n  .own-runwayml .rw-burger { display: flex; }\n  .own-runwayml .rw-grid { grid-template-columns: 1fr 1fr; }\n  .own-runwayml .rw-tile-lg { grid-column: span 2; grid-row: auto; }\n  .own-runwayml .rw-articles { grid-template-columns: 1fr 1fr; }\n  .own-runwayml .rw-stats-grid { grid-template-columns: 1fr 1fr; }\n  .own-runwayml .rw-foot-inner { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-runwayml .rw-link { display: none; }\n  .own-runwayml .rw-hero { min-height: 560px; }\n  .own-runwayml .rw-hero-inner { padding-top: 96px; }\n  .own-runwayml .rw-h1 { font-size: clamp(34px, 10cqi, 44px); letter-spacing: -.8px; }\n  .own-runwayml .rw-grid { grid-template-columns: 1fr; }\n  .own-runwayml .rw-tile-lg { grid-column: auto; }\n  .own-runwayml .rw-articles { grid-template-columns: 1fr; }\n  .own-runwayml .rw-stats-grid { grid-template-columns: 1fr 1fr; }\n  .own-runwayml .rw-mission { padding: 64px var(--gut); }\n}\n@container frame (max-width: 430px) {\n  .own-runwayml .rw-h1 { font-size: 34px; }\n  .own-runwayml .rw-hero-sub { font-size: 14px; }\n  .own-runwayml .rw-stats-grid { grid-template-columns: 1fr; }\n  .own-runwayml .rw-foot-inner { grid-template-columns: 1fr; }\n  .own-runwayml .rw-trust-bar { gap: 14px 28px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-runwayml *, .own-runwayml *::before, .own-runwayml *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Runway-language chrome for showcase.html ═══════════════════
   Registers window.OWN_LAYOUTS['runwayml'].init(root). The editorial layout is
   static (CSS + SVG only), so init returns a no-op cleanup; the guard keeps an
   inert anchor from navigating away from the showcase frame. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['runwayml'] = {
    init: function () {
      return function cleanup() { /* static layout — nothing to tear down */ };
    }
  };
})();
